import { Text, Button, Card } from "@nextui-org/react";
import { motion } from "framer-motion";
import {
  TbChartBar,
  TbPaperBag,
  TbArrowAutofitUp,
  TbChartArcs,
  TbLogout,
  TbBrandAdobe,
  TbCalculator,
  TbPlus,
  TbList,
  TbCashBanknoteOff,
  TbLayoutList,
} from "react-icons/tb";
import { Link } from "react-router-dom";
import { useDispatch, useSelector } from "react-redux";
import { invtryActions } from "../redux/inventorySlice";

const MotionText = motion(Text);
const MotionCard = motion(Card);

const btnAnim = {
  whileTap: { scale: 0.9 },
  whileHover: { scale: 1.05 },
};

const Home = () => {
  const dispatch = useDispatch();
  const level = useSelector((state) => state.invtry.level);

  const logout = () => {
    dispatch(invtryActions.revokeAuth());
    localStorage.removeItem("token");
  };

  return (
    <motion.div className="alignDivCenter homeDiv">
      <MotionText h2>Marvans</MotionText>
      <MotionCard
        variant="bordered"
        css={{ mw: "550px", mt: "50px", border: "none", height: "fit-content" }}
      >
        <Card.Body className="homeActionCon">
          <Link to="/analytics/report">
            <motion.div className="homeAction" {...btnAnim}>
              <Text size="40px">
                <TbChartBar />
              </Text>
              <Text b>Reports</Text>
            </motion.div>
          </Link>

          <Link to="/analytics/inventory">
            <motion.div className="homeAction" {...btnAnim}>
              <Text size="40px">
                <TbPaperBag />
              </Text>
              <Text b>Inventory</Text>
            </motion.div>
          </Link>
          <Link to="/analytics/inventory2">
            <motion.div className="homeAction" {...btnAnim}>
              <Text size="40px">
                <TbPaperBag />
              </Text>
              <Text b>HOI</Text>
            </motion.div>
          </Link>
          <Link to="/analytics/inventory3">
            <motion.div className="homeAction" {...btnAnim}>
              <Text size="40px">
                <TbPaperBag />
              </Text>
              <Text b>SUNIL</Text>
            </motion.div>
          </Link>
          {level === "premium" && (
            <Link to="/analytics/pdfs">
              <motion.div className="homeAction" {...btnAnim}>
                <Text size="40px">
                  <TbBrandAdobe />
                </Text>
                <Text b>Daily PDF</Text>
              </motion.div>
            </Link>
          )}
          {level === "premium" && (
            <Link to="/analytics/calculator">
              <motion.div className="homeAction" {...btnAnim}>
                <Text size="40px">
                  <TbCalculator />
                </Text>
                <Text b>Calculator</Text>
              </motion.div>
            </Link>
          )}
          <Link to="/analytics/udhars">
            <motion.div className="homeAction" {...btnAnim}>
              <Text size="40px">
                <TbCashBanknoteOff />
              </Text>
              <Text b>Udhar</Text>
            </motion.div>
          </Link>
          <Link to="/analytics/add">
            <motion.div className="homeAction" {...btnAnim}>
              <Text size="40px">
                <TbPlus />
              </Text>
              <Text b>Add Product</Text>
            </motion.div>
          </Link>
          <Link to="/analytics/view">
            <motion.div className="homeAction" {...btnAnim}>
              <Text size="40px">
                <TbList />
              </Text>
              <Text b>View Products</Text>
            </motion.div>
          </Link>
          <a
            href="https://scan.mrsaini.com"
            target="_blank"
            rel="noopener noreferrer"
          >
            <motion.div className="homeAction" {...btnAnim}>
              <Text size="40px">
                <TbArrowAutofitUp />
              </Text>
              <Text b>Updates</Text>
            </motion.div>
          </a>
          <motion.div className="homeAction" {...btnAnim} onClick={logout}>
            <Text size="40px">
              <TbLogout />
            </Text>
            <Text b>Logout</Text>
          </motion.div>
        </Card.Body>
      </MotionCard>
    </motion.div>
  );
};

export default Home;
